import argparse


def build_parser():
    parser = argparse.ArgumentParser()
    parser.add_argument("--entrada", default="datos")
    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)
    return 0 if args.entrada else 1


if __name__ == "__main__":
    raise SystemExit(main())

try:
    open("datos.json", encoding="utf-8")
except:
    pass

$nested = [ordered]@{ a = [ordered]@{ b = [ordered]@{ c = [ordered]@{ d = 42 } } } }
$deep = ($nested | ConvertTo-Json -Depth 5) | ConvertFrom-Json
$shallow = ($nested | ConvertTo-Json -Depth 1 -WarningAction SilentlyContinue) | ConvertFrom-Json
$out = [ordered]@{
  depth5_preserved = ($deep.a.b.c.d -eq 42)
  depth1_c_is_object = ($shallow.a.b.c -is [System.Management.Automation.PSCustomObject])
  depth1_deep_value = $(if ($shallow.a.b.c -is [System.Management.Automation.PSCustomObject]) { $shallow.a.b.c.d } else { "truncated" })
}
Write-Output ("RESULT:" + ($out | ConvertTo-Json -Depth 10 -Compress))

$tickets = @(
  [pscustomobject]@{ id = "1"; estado = "abierto" },
  [pscustomobject]@{ id = "2"; estado = "cerrado" },
  [pscustomobject]@{ id = "3"; estado = "abierto" }
)
$abiertos = @($tickets | Where-Object { $_.estado -eq "abierto" })
$out = [ordered]@{
  count = $abiertos.Count
  ids = ($abiertos.id -join ",")
  objects_preserved = ($abiertos[0].PSObject.Properties.Name -contains "estado")
}
Write-Output ("RESULT:" + ($out | ConvertTo-Json -Depth 10 -Compress))

$tickets = @(
  [pscustomobject]@{ id = "1"; prioridad = "alta"; secreto = "x" },
  [pscustomobject]@{ id = "2"; prioridad = "baja"; secreto = "y" }
)
$projected = @($tickets | Select-Object -Property id, prioridad)
$names = (@($projected[0].PSObject.Properties.Name) -join ",")
$out = [ordered]@{
  count = $projected.Count
  names = $names
  first_id = $projected[0].id
  has_secreto = ($names -match "secreto")
}
Write-Output ("RESULT:" + ($out | ConvertTo-Json -Depth 10 -Compress))

$tickets = @(
  [pscustomobject]@{ id = "1"; categoria = "red" },
  [pscustomobject]@{ id = "2"; categoria = "app" },
  [pscustomobject]@{ id = "3"; categoria = "red" }
)
$groups = @($tickets | Group-Object -Property categoria)
$red = @($groups | Where-Object { $_.Name -eq "red" })
$out = [ordered]@{
  group_count = $groups.Count
  red_member_count = @($red)[0].Count
  names = (($groups.Name | Sort-Object) -join ",")
}
Write-Output ("RESULT:" + ($out | ConvertTo-Json -Depth 10 -Compress))

$items = @(
  [pscustomobject]@{ importe = 10 },
  [pscustomobject]@{ importe = 20 },
  [pscustomobject]@{ importe = 30 }
)
$m = $items | Measure-Object -Property importe -Sum -Average
$out = [ordered]@{ sum = $m.Sum; count = $m.Count; average = $m.Average }
Write-Output ("RESULT:" + ($out | ConvertTo-Json -Depth 10 -Compress))

$missing = Join-Path $env:B2_SNIPPET_TEMP "missing.txt"
$withStop = $false
try { Get-Item -LiteralPath $missing -ErrorAction Stop | Out-Null } catch { $withStop = $true }
$withoutStop = $false
try { Get-Item -LiteralPath $missing -ErrorAction SilentlyContinue | Out-Null } catch { $withoutStop = $true }
$finallyRan = $false
try { throw "previsto" } catch { $finallyRan = $true } finally { $finallyRan = $true }
$out = [ordered]@{
  catch_with_stop = $withStop
  catch_without_stop = $withoutStop
  finally_ran = $finallyRan
  planned_exit_code = 3
}
Write-Output ("RESULT:" + ($out | ConvertTo-Json -Depth 10 -Compress))

$captured = (& {
  Write-Verbose "b2-verbose" -Verbose
  Write-Warning "b2-warning"
  Write-Error "b2-error" -ErrorAction Continue
  Write-Output "b2-output"
} 4>&1 3>&1 2>&1) | ForEach-Object { $_.ToString() }
$joined = $captured -join ";"
$out = [ordered]@{
  has_verbose = $joined.Contains("b2-verbose")
  has_warning = $joined.Contains("b2-warning")
  has_error = $joined.Contains("b2-error")
  has_output = $joined.Contains("b2-output")
}
Write-Output ("RESULT:" + ($out | ConvertTo-Json -Depth 10 -Compress))
